import{bQ as e,aL as a,u as d,G as r}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"用户币币账户缓存","description":"UserBBAccountCache 与 UserBBCoinWallet：撮合侧可用/冻结权威态。","frontmatter":{"title":"用户币币账户缓存","description":"UserBBAccountCache 与 UserBBCoinWallet：撮合侧可用/冻结权威态。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070802"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070802"}],["meta",{"property":"og:title","content":"用户币币账户缓存 · TGEX"}],["meta",{"property":"og:description","content":"UserBBAccountCache 与 UserBBCoinWallet：撮合侧可用/冻结权威态。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"用户币币账户缓存 · TGEX"}],["meta",{"name":"twitter:description","content":"UserBBAccountCache 与 UserBBCoinWallet：撮合侧可用/冻结权威态。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"用户币币账户缓存\\",\\"description\\":\\"UserBBAccountCache 与 UserBBCoinWallet：撮合侧可用/冻结权威态。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070802\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070802\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070802.md","filePath":"07.现货手册/08.缓存模型/02.用户币币账户缓存.md"}'),o={name:"pages/070802.md"};function n(i,t,l,s,p,g){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="用户币币账户缓存" tabindex="-1">用户币币账户缓存 <a class="header-anchor" href="#用户币币账户缓存" aria-label="Permalink to &quot;用户币币账户缓存&quot;">​</a></h1><p>现货交易一刻不停地改写「还能用多少、已经占了多少」。若这笔账放在撮合之外，下单占用、盘口成交、撤单退回就要跨服务来回确认，延迟与半成功都会拖垮热路径。因此撮合进程按用户与币种就地记住可用与冻结：谁进簿，谁改账；占用、划转、释放与订单簿同一处串行落定，交易主链不再绕道问账务。</p><h2 id="索引结构" tabindex="-1">索引结构 <a class="header-anchor" href="#索引结构" aria-label="Permalink to &quot;索引结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Table&lt;userId, coinId, UserBBCoinWallet&gt;</span></span></code></pre></div><p>整张表可以想成一张二维账本：行是用户，列是币种，格子里是该用户在该币种下的钱包。查「某人某币还有多少可用、冻了多少」，一次按行键 + 列键定位即可；装入时也是同一坐标覆盖或写入。</p><p>实现上用 Guava 的 HashBasedTable 存这份二维关系，再包一层 Tables.synchronizedTable，保证多处读写时表结构本身的并发安全。真正改可用与冻结时，仍以撮合事件串行为准——同步表只护住「格子怎么取、怎么放」，不替代业务上的先记账再进簿。</p><p>索引只拆到用户 × 币种，不再为商户加第三维。同一用户同一币种在撮合侧只有一条钱包；商户身份记在钱包对象的 partnerId 上，供流水、分成等携带上下文，而不参与寻址。这样热路径键最短，也避免「同一用户因商户维度被拆成多份余额」的歧义。</p><h2 id="钱包字段" tabindex="-1">钱包字段 <a class="header-anchor" href="#钱包字段" aria-label="Permalink to &quot;钱包字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>含义</th><th>备注</th></tr></thead><tbody><tr><td>id</td><td>Long</td><td>钱包主键</td><td>与账务侧币币钱包记录对应</td></tr><tr><td>partnerId</td><td>Long</td><td>商户 id</td><td>不参与 Table 键；挂在对象上便于流水与分成</td></tr><tr><td>userId</td><td>Long</td><td>用户 id</td><td>与 Table 行键一致</td></tr><tr><td>coinId</td><td>Long</td><td>币种 id</td><td>与 Table 列键一致</td></tr><tr><td>total</td><td>AtomicLong</td><td>可用 · 整数部分</td><td>热路径加减改此字段</td></tr><tr><td>totalDecimal</td><td>AtomicLong</td><td>可用 · 小数部分</td><td>与 total 拼成完整可用；对外见 getTotalBigDecimal</td></tr><tr><td>frozen</td><td>AtomicLong</td><td>冻结 · 整数部分</td><td>下单占用、成交/撤单释放</td></tr><tr><td>frozenDecimal</td><td>AtomicLong</td><td>冻结 · 小数部分</td><td>与 frozen 拼成完整冻结；对外见 getFrozenBigDecimal</td></tr><tr><td>paTotal</td><td>AtomicLong</td><td>商户手续费暂存</td><td>成交计费时累加，供后续结算/分成</td></tr><tr><td>adTotal</td><td>AtomicLong</td><td>平台手续费暂存</td><td>成交计费时累加，供后续结算</td></tr><tr><td>version</td><td>AtomicInteger</td><td>版本号</td><td>每次可用/冻结加减成功后递增</td></tr><tr><td>createTime</td><td>Date</td><td>创建时间</td><td>钱包装入缓存时带入</td></tr><tr><td>updateTime</td><td>Date</td><td>修改时间</td><td>冻结/解冻等改账成功后刷新</td></tr></tbody></table><p>数量在热路径用定点整数运算；对外预检、落库常用 BigDecimal 口径（getTotalBigDecimal / getFrozenBigDecimal）。</p><h2 id="如何写进来、如何改" tabindex="-1">如何写进来、如何改 <a class="header-anchor" href="#如何写进来、如何改" aria-label="Permalink to &quot;如何写进来、如何改&quot;">​</a></h2><p>缓存里的格子不会凭空出现，也不会在进程外被直接改掉。写入大致分两类：<strong>装入快照</strong>与<strong>在快照上做增量</strong>。</p><h3 id="装入-格子从哪来" tabindex="-1">装入：格子从哪来 <a class="header-anchor" href="#装入-格子从哪来" aria-label="Permalink to &quot;装入：格子从哪来&quot;">​</a></h3><p>某用户某币种第一次被交易碰到时，按「内存 → Redis → MySQL → 必要时新建」补齐，再 <code>put</code> 进 Table：</p><ol><li>内存已有 → 直接用，不再回源。</li><li>内存没有 → 读 Redis 里该用户币种快照；有则装入内存。</li><li>Redis 也没有 → 读 MySQL 币币钱包；有则装入内存，并回写 Redis。</li><li>库中也没有 → 初始化一条零余额钱包写入库与缓存。</li></ol><p>撮合启动恢复未完结委托时，会按委托涉及到的用户与币种批量从 Redis 预热进本表，避免开盘后第一笔才冷启动。同一用户装入过程会串行化，避免并发首次加载写出两份钱包。</p><h3 id="修改-谁在改格子里的数" tabindex="-1">修改：谁在改格子里的数 <a class="header-anchor" href="#修改-谁在改格子里的数" aria-label="Permalink to &quot;修改：谁在改格子里的数&quot;">​</a></h3><p>装入之后，<strong>可用 / 冻结只在撮合事件处理链上改内存对象本身</strong>，一般不再整对象覆盖：</p><table tabindex="0"><thead><tr><th>来源</th><th>改什么</th></tr></thead><tbody><tr><td>下单受理</td><td>对应币种：<strong>可用 → 冻结</strong>（详见<a href="#total-to-frozen">下一节</a>）</td></tr><tr><td>撤单出簿</td><td>剩余占用：冻结 → 可用</td></tr><tr><td>成交比价</td><td>双方解冻占用、划转入账、累计手续费暂存；买方可能退回多冻部分</td></tr><tr><td>充值 / 提现 / 调账等外部变动</td><td>先保证钱包已装入，再以「改账事件」进同一处理链，对可用或冻结做加减（或可用↔冻结对调）</td></tr></tbody></table><p>改成功会带出账务流水意向，写入 Redis 缓冲，由后台异步刷进 MySQL。流水<strong>不</strong>作为 Table 里的常驻数据；查询展示可走库或检索，热路径只认内存钱包。</p><p>委托侧余额预检只读本表快照，<strong>不写</strong>；真正占用发生在撮合受理那一次增量。</p><h2 id="total-to-frozen" tabindex="-1">增量：可用 → 冻结 <a class="header-anchor" href="#total-to-frozen" aria-label="Permalink to &quot;增量：可用 → 冻结 {#total-to-frozen}&quot;">​</a></h2><p>下单受理时，撮合在内存钱包上做的占用动作。钱仍在<strong>同一用户、同一币种</strong>的格子里：只是从「还能用」变成「已被挂单占用」——<strong>不是</strong>转到卖方或其它账户。买卖双方之间的资产交换发生在后续成交，不在本步骤。</p><p>在整条交易链上的位置：见<a href="/pages/070508#bookkeeping">撮合主流程 · 冻结建单</a>。本节只写<strong>格子怎么被改</strong>。</p><h3 id="调用前要满足什么" tabindex="-1">调用前要满足什么 <a class="header-anchor" href="#调用前要满足什么" aria-label="Permalink to &quot;调用前要满足什么&quot;">​</a></h3><ul><li>Table 里已有 <code>(userId, coinId)</code> 格子（通常入口已 <code>load</code>；本步骤不做「从库新建钱包」）。</li><li>调用方已算好：冻哪个币、冻多少（买冻计价币金额，卖冻基础币数量；引擎内为定点整数）。</li><li>事件处在撮合处理链上（与进簿同链串行），避免旁路改余额。</li></ul><h3 id="逐步怎么做" tabindex="-1">逐步怎么做 <a class="header-anchor" href="#逐步怎么做" aria-label="Permalink to &quot;逐步怎么做&quot;">​</a></h3><ol><li><p><strong>按键取钱包</strong><br><code>get(userId, coinId)</code>。格子不存在 → 失败（无资产可改），整笔下单终止。</p></li><li><p><strong>在钱包对象上做可用 → 冻结</strong><br> 同一 <code>UserBBCoinWallet</code> 内顺序执行：</p><ul><li>先按数量<strong>减少可用</strong>（整数部分 + 小数部分一并处理；可用不足则整步失败，冻结不变）。</li><li>再<strong>增加冻结</strong>同额。<br> 任一步失败 → 本步骤失败，不生成成功流水；调用方不得继续写委托热数据、不得进簿。</li></ul></li><li><p><strong>刷新修改时间</strong><br> 成功后更新 <code>updateTime</code>；可用/冻结加减成功时 <code>version</code> 递增。</p></li><li><p><strong>记下流水意向</strong><br> 生成一条撮合侧账务流水意向，典型变动口径为：可用变动为负、冻结变动为正（同额），并带上业务类型（委托占用一类）与业务单号（如委托号）。<br> 流水意向随后由处理链写入 Redis 缓冲，异步落库；<strong>流水本身不常驻 Table</strong>。</p></li></ol><h3 id="成功-失败之后" tabindex="-1">成功 / 失败之后 <a class="header-anchor" href="#成功-失败之后" aria-label="Permalink to &quot;成功 / 失败之后&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结果</th><th>内存钱包</th><th>调用方通常接着做什么</th></tr></thead><tbody><tr><td>成功</td><td>可用已减、冻结已加</td><td>写 Redis 本笔增量、写委托热数据，再进入订单簿</td></tr><tr><td>失败（无格子 / 可用不足等）</td><td>应保持未成功占用</td><td>整笔下单失败；不建热委托、不进盘口</td></tr></tbody></table><p>对称操作是 <strong>冻结 → 可用</strong>（撤单退回剩余占用）：先减冻结、再加可用，同样只动同一格子。成交路径则会解冻占用并在买卖双方之间划转，属于另一类增量，不在本节展开。</p><h2 id="如何保证一致性" tabindex="-1">如何保证一致性 <a class="header-anchor" href="#如何保证一致性" aria-label="Permalink to &quot;如何保证一致性&quot;">​</a></h2><p>这里说的一致，主要指：<strong>同一用户币种上的可用/冻结，与未完结委托占用、成交结果对得上</strong>；以及进程崩溃后能靠 Redis / 库把权威态找回来。</p><ol><li><p><strong>权威在内存，改账跟进簿同链</strong><br> 下单先改钱包再进订单簿；成交、撤单也在同一条撮合处理链上改剩余量与冻结。同一交易对事件串行，不会出现「簿上还有单、冻结已被旁路解掉」或「已成交却未解冻」这类交叉写。</p></li><li><p><strong>先校验再加减，失败不进簿</strong><br> 可用不够不冻、冻结不够不成交；加减失败则本事件失败（同步调用方拿到错误），不会带着半成功余额去挂单。多步成交改账内部带回滚补偿路径，避免半步成功留下脏数。</p></li><li><p><strong>外部资金变动也进撮合改账通道</strong><br> 充提等不直改 MySQL 当撮合真相，而是变成撮合侧的改账事件，与交易事件共用处理链，从而与挂单占用抢同一份可用/冻结。路径见<a href="/pages/070511">充提改账协同</a>。</p></li><li><p><strong>装入只补洞，不覆盖热路径正在改的权威</strong><br> 已在内存的格子优先用内存；回源只发生在格子缺失时。版本号随每次加减递增，便于旁路识别变更次序。</p></li><li><p><strong>持久化是增量旁路，不是第二权威</strong><br> Redis / MySQL 承接快照与流水，供恢复与对账；运行中以内存为准。刷库积压或恢复顺序异常时，以撮合未完结委托 + Redis 缓冲重放装入为准，而不是用过期页面余额倒推。</p></li></ol><p>委托预检与真实冻结之间仍可能有时间差（预检够、稍后受理时不够）——这是刻意的：预检不占坑，最终以受理瞬间串行改账结果为准。</p><p>详见<a href="/pages/070502">下单主流程</a>、<a href="/pages/070508">撮合主流程</a>、<a href="/pages/070511">充提改账协同</a>、<a href="/pages/070512">手续费计费落地</a>。同组：<a href="/pages/070801">缓存总览</a>。</p>',36)])])}const b=e(o,[["render",n]]);export{c as __pageData,b as default};
